class Solution:
    def minimumDifference(self, nums: list[int], k: int) -> int:
        nums.sort()                                    # O(n log n) dominates
        return min(nums[i + k - 1] - nums[i]           # window of k consecutive sorted scores
                   for i in range(len(nums) - k + 1))  # n - k + 1 windows, O(1) each
